import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"@svta/cml-c2pa changelog","description":"","frontmatter":{},"headers":[],"relativePath":"packages/c2pa/changelog.md","filePath":"packages/c2pa/changelog.md"}`),a={name:`packages/c2pa/changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="svta-cml-c2pa-changelog" tabindex="-1">@svta/cml-c2pa changelog <a class="header-anchor" href="#svta-cml-c2pa-changelog" aria-label="Permalink to “@svta/cml-c2pa changelog”">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.7.0...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to “Unreleased”">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Every code example in the guides now typechecks (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/565" target="_blank" rel="noreferrer">#565</a>).</li><li>The README no longer describes the peer dependencies. The website lists them from <code>package.json</code> on the package page.</li></ul><h2 id="_1-7-0-2026-10-22" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.6.0...c2pa-v1.7.0" target="_blank" rel="noreferrer">1.7.0</a> - 2026-10-22 <a class="header-anchor" href="#_1-7-0-2026-10-22" aria-label="Permalink to “1.7.0 - 2026-10-22”">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>validateC2paInitSegment</code>, <code>validateC2paSegment</code>, <code>validateC2paManifestBoxSegment</code>, and <code>validateC2paMerkleSegment</code> now hash a root box with a <code>largesize</code> header or a size of 0. The content hash also covers every root box after such a box (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/566" target="_blank" rel="noreferrer">#566</a>).</li><li><code>validateC2paInitSegment</code>, <code>validateC2paSegment</code>, <code>validateC2paManifestBoxSegment</code>, and <code>validateC2paMerkleSegment</code> now exclude only the nested box for an xpath such as <code>/moov/udta</code>. The content hash keeps the other bytes of the root box (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/567" target="_blank" rel="noreferrer">#567</a>).</li><li><code>BmffHashExclusion</code> now has the <code>length</code>, <code>subset</code>, <code>version</code>, <code>flags</code>, and <code>exact</code> fields of C2PA section 18.6.2. The <code>length</code>, <code>version</code>, <code>flags</code>, and <code>exact</code> fields narrow the match to a box with those values. The <code>subset</code> field excludes only the listed byte ranges of the box (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/567" target="_blank" rel="noreferrer">#567</a>).</li><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now fail with <code>C2paStatusCode.ASSERTION_BMFFHASH_MALFORMED</code> for a malformed exclusion. Malformed means an xpath outside the grammar of C2PA section 18.6.2, or a field of the wrong type (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/567" target="_blank" rel="noreferrer">#567</a>).</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The manifest box guide states that <code>C2paStatusCode.CLAIM_HARD_BINDINGS_MISSING</code> appears only for a manifest with a claim that decodes.</li><li>The README now has a When to use section. The section names the tasks that the package covers and the entry point of each task.</li></ul><h2 id="_1-6-0-2026-10-21" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.5.0...c2pa-v1.6.0" target="_blank" rel="noreferrer">1.6.0</a> - 2026-10-21 <a class="header-anchor" href="#_1-6-0-2026-10-21" aria-label="Permalink to “1.6.0 - 2026-10-21”">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h3><ul><li><code>validateC2paInitSegment</code> now fails an init segment without a <code>c2pa.hash.bmff.v3</code> assertion with <code>LiveVideoStatusCode.INIT_INVALID</code>. The result for a manifest without any hard binding assertion also includes <code>C2paStatusCode.CLAIM_HARD_BINDINGS_MISSING</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/552" target="_blank" rel="noreferrer">#552</a>).</li><li><code>validateC2paInitSegment</code> now fails with <code>LiveVideoStatusCode.INIT_INVALID</code> if the init content hash does not include the <code>moov</code> box (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/552" target="_blank" rel="noreferrer">#552</a>).</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now fail a segment if the CBOR or JSON of an assertion does not decode. The result includes the new <code>C2paStatusCode.ASSERTION_CBOR_INVALID</code> or <code>C2paStatusCode.ASSERTION_JSON_INVALID</code>.</li><li>The validation functions now reject a CBOR map with a duplicate key. A claim or an assertion with such a map fails with <code>C2paStatusCode.CLAIM_CBOR_INVALID</code> or <code>C2paStatusCode.ASSERTION_CBOR_INVALID</code>. Keys such as <code>1</code> and <code>&quot;1&quot;</code> count as duplicates (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/516" target="_blank" rel="noreferrer">#516</a>).</li><li><code>validateC2paInitSegment</code> no longer reports <code>LiveVideoStatusCode.SESSIONKEY_INVALID</code> for an init segment without a <code>c2pa.session-keys</code> assertion (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/555" target="_blank" rel="noreferrer">#555</a>). The C2PA Manifest Box method of C2PA 2.4 section 19.3 needs no session keys. A <code>c2pa.session-keys</code> assertion with an invalid key, or with no key, still reports <code>SESSIONKEY_INVALID</code>.</li><li><code>validateC2paInitSegment</code> no longer reports <code>SESSIONKEY_INVALID</code> for an init segment whose session keys have all expired. The result has an empty <code>sessionKeys</code> list, and each VSI segment then fails with <code>LiveVideoStatusCode.SEGMENT_INVALID</code>, as C2PA 2.4 section 19.7.3 requires.</li><li><code>SESSIONKEY_INVALID</code> no longer means that the init segment has no valid session key. To detect that case, check <code>sessionKeys.length === 0</code> on the result of <code>validateC2paInitSegment</code>.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>validateC2paManifestBoxSegment</code> now reports a missing hard binding only for a manifest with a claim that decodes. A manifest with a claim code such as <code>C2paStatusCode.CLAIM_MISSING</code> no longer also reports <code>C2paStatusCode.CLAIM_HARD_BINDINGS_MISSING</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/552" target="_blank" rel="noreferrer">#552</a>).</li></ul><h2 id="_1-5-0-2026-10-21" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.4.1...c2pa-v1.5.0" target="_blank" rel="noreferrer">1.5.0</a> - 2026-10-21 <a class="header-anchor" href="#_1-5-0-2026-10-21" aria-label="Permalink to “1.5.0 - 2026-10-21”">​</a></h2><h3 id="security-1" tabindex="-1">Security <a class="header-anchor" href="#security-1" aria-label="Permalink to “Security”">​</a></h3><ul><li><code>validateC2paManifestBoxSegment</code> now fails a segment whose manifest has no <code>c2pa.hash.bmff.v3</code> assertion. The result includes <code>LiveVideoStatusCode.SEGMENT_INVALID</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/522" target="_blank" rel="noreferrer">#522</a>).</li><li><code>validateC2paManifestBoxSegment</code> now fails a segment whose <code>c2pa.hash.bmff.v3</code> assertion is not a map, has no <code>hash</code>, or has only a <code>value</code> field. The result includes <code>C2paStatusCode.ASSERTION_BMFFHASH_MALFORMED</code>.</li><li><code>validateC2paInitSegment</code> now fails with <code>C2paStatusCode.ASSERTION_BMFFHASH_MALFORMED</code> for a malformed <code>c2pa.hash.bmff.v3</code> assertion (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/550" target="_blank" rel="noreferrer">#550</a>). Malformed means not a map, no <code>hash</code> and no Merkle maps, or only a <code>value</code> field.</li><li><code>validateC2paInitSegment</code> no longer returns <code>sessionKeys</code> or <code>merkleMaps</code> for an init segment that fails a content hash check. This covers a flat hash or a Merkle <code>initHash</code> that does not match, and a Merkle map that does not conform.</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>C2paStatusCode</code> now has <code>CLAIM_HARD_BINDINGS_MISSING</code> (<code>claim.hardBindings.missing</code>). <code>validateC2paManifestBoxSegment</code> reports it for a manifest without any hard binding assertion.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>validateC2paSegment</code> no longer fails a segment after a gap in the sequence numbers, so the authentic segment after a tampered segment passes (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/546" target="_blank" rel="noreferrer">#546</a>). <code>result.sequenceResult</code> still reports <code>SequenceValidationReason.GAP_DETECTED</code> with <code>missingFrom</code> and <code>missingTo</code>.</li><li><code>validateC2paSegment</code> now reports <code>LiveVideoStatusCode.SEGMENT_INVALID</code> instead of <code>LiveVideoStatusCode.ASSERTION_INVALID</code> for a duplicate, out-of-order, or below-minimum sequence number. The order check is a library rule with the code of the C2PA 2.5 draft. If your application handles <code>livevideo.assertion.invalid</code> for VSI segments, handle <code>livevideo.segment.invalid</code> instead.</li><li><code>validateC2paManifestBoxSegment</code> now chains <code>previousManifestId</code> to the manifest identifier of the previous segment, the <code>urn:c2pa:</code> JUMBF label, and compares the identifiers exactly (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/545" target="_blank" rel="noreferrer">#545</a>). It no longer removes an <code>xmp:iid:</code> or <code>urn:uuid:</code> prefix or ignores case.</li><li>The JUMBF label counts as the manifest identifier only if the claim <code>signature</code> URI names it, in the absolute form <code>self#jumbf=/c2pa/&lt;label&gt;/c2pa.signature</code>. For a URI relative to the manifest, such as <code>self#jumbf=c2pa.signature</code>, <code>validateC2paManifestBoxSegment</code> fails with <code>LiveVideoStatusCode.SEGMENT_INVALID</code> and <code>validateC2paInitSegment</code> returns a <code>null</code> <code>manifestId</code>. A changed label therefore cannot take the identity of an omitted segment.</li><li>A claim without a <code>signature</code> URI now fails with <code>C2paStatusCode.CLAIM_SIGNATURE_MISSING</code>. So does a URI that does not resolve to the signature box of the same manifest. <code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> both report it.</li><li>A claim <code>instanceID</code>, <code>claim_generator</code>, or <code>dc:title</code> that is not a text string now counts as absent. <code>C2paManifest.instanceId</code> is <code>null</code> for such an <code>instanceID</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/521" target="_blank" rel="noreferrer">#521</a>).</li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>nextManifestId</code> and <code>InitSegmentValidation.manifestId</code> now hold the <code>urn:c2pa:</code> URN of the manifest instead of the claim <code>instanceID</code>. The <code>manifestId</code> of a Verifiable Segment Info now matches the <code>manifestId</code> of its init segment. If your application stores a <code>lastManifestId</code> between sessions, discard values that it stored with an earlier version.</li><li><code>validateC2paInitSegment</code> reports a <code>c2pa.hash.bmff.v3</code> assertion with a <code>hash</code> that is not a byte string with <code>C2paStatusCode.ASSERTION_BMFFHASH_MALFORMED</code> instead of <code>LiveVideoStatusCode.INIT_INVALID</code>. The same code replaces <code>INIT_INVALID</code> for exclusions that do not conform to C2PA section 18.6. Handle <code>ASSERTION_BMFFHASH_MALFORMED</code> where you handle <code>INIT_INVALID</code>.</li><li>A flat content hash that does not match now adds <code>C2paStatusCode.ASSERTION_BMFFHASH_MISMATCH</code> next to <code>LiveVideoStatusCode.INIT_INVALID</code>.</li></ul><h2 id="_1-4-1-2026-10-18" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.4.0...c2pa-v1.4.1" target="_blank" rel="noreferrer">1.4.1</a> - 2026-10-18 <a class="header-anchor" href="#_1-4-1-2026-10-18" aria-label="Permalink to “1.4.1 - 2026-10-18”">​</a></h2><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Narrow the <code>@svta/cml-iso-bmff</code> and <code>@svta/cml-utils</code> peer dependency ranges from <code>&gt;=</code> to <code>^</code>. The published package no longer accepts a later major version of either peer.</li></ul><h2 id="_1-4-0-2026-10-10" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.3.0...c2pa-v1.4.0" target="_blank" rel="noreferrer">1.4.0</a> - 2026-10-10 <a class="header-anchor" href="#_1-4-0-2026-10-10" aria-label="Permalink to “1.4.0 - 2026-10-10”">​</a></h2><h3 id="security-2" tabindex="-1">Security <a class="header-anchor" href="#security-2" aria-label="Permalink to “Security”">​</a></h3><ul><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now reject a manifest whose assertion store holds two or more boxes with the same label. The result includes <code>C2paStatusCode.ASSERTION_MISSING</code> when the claim references that label, or <code>ASSERTION_UNDECLARED</code> when it does not (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-7jrg-x839-w8wv" target="_blank" rel="noreferrer">GHSA-7jrg-x839-w8wv</a>).</li><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now reject a manifest with more than one hard binding assertion. The result includes the new <code>C2paStatusCode.ASSERTION_MULTIPLE_HARD_BINDINGS</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-7jrg-x839-w8wv" target="_blank" rel="noreferrer">GHSA-7jrg-x839-w8wv</a>).</li><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now reject a manifest whose assertion store holds an assertion the claim does not reference. The result includes the new <code>C2paStatusCode.ASSERTION_UNDECLARED</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-7jrg-x839-w8wv" target="_blank" rel="noreferrer">GHSA-7jrg-x839-w8wv</a>).</li><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now reject a manifest with more than one claim box. The result includes the new <code>C2paStatusCode.CLAIM_MULTIPLE</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-7jrg-x839-w8wv" target="_blank" rel="noreferrer">GHSA-7jrg-x839-w8wv</a>).</li><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now reject a manifest with more than one assertion store. The result includes <code>C2paStatusCode.ASSERTION_MISSING</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-7jrg-x839-w8wv" target="_blank" rel="noreferrer">GHSA-7jrg-x839-w8wv</a>).</li><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now reject a manifest with more than one signature box. The result includes <code>C2paStatusCode.CLAIM_SIGNATURE_MISSING</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-7jrg-x839-w8wv" target="_blank" rel="noreferrer">GHSA-7jrg-x839-w8wv</a>).</li><li><code>validateC2paManifestBoxSegment</code> now reads <code>sequenceNumber</code>, <code>streamId</code>, <code>previousManifestId</code>, <code>continuityMethod</code>, and <code>bmffHashHex</code> only from assertions whose hash matches a claim reference. Each field is <code>null</code> otherwise. Check <code>isValid</code> before you use any field (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-7jrg-x839-w8wv" target="_blank" rel="noreferrer">GHSA-7jrg-x839-w8wv</a>).</li><li><code>validateC2paInitSegment</code> now returns empty <code>sessionKeys</code> and <code>merkleMaps</code> when any manifest integrity check fails. Check <code>isValid</code> before you use either list (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-7jrg-x839-w8wv" target="_blank" rel="noreferrer">GHSA-7jrg-x839-w8wv</a>).</li><li><code>validateC2paManifestBoxSegment</code> no longer updates <code>nextManifestId</code> and <code>nextState</code> from a segment that fails verification, is on another stream, or does not move the sequence number forward. A segment that fails only the continuity check still updates them, so a stream recovers after a lost or rejected segment. After a seek, an encoder restart, or a new stream ID, pass <code>null</code> as <code>lastManifestId</code> and <code>undefined</code> as <code>state</code> to start a new state (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-jjpj-wgh4-rm9c" target="_blank" rel="noreferrer">GHSA-jjpj-wgh4-rm9c</a>).</li><li><code>validateC2paSegment</code> no longer updates <code>nextSequenceState</code> from a segment whose signature or content hash does not verify. The same applies to a segment whose session key is missing, not yet active, or expired. A replayed or forged sequence number from such a segment no longer affects later segments (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-jjpj-wgh4-rm9c" target="_blank" rel="noreferrer">GHSA-jjpj-wgh4-rm9c</a>).</li></ul><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>C2paStatusCode</code> now has <code>ASSERTION_MULTIPLE_HARD_BINDINGS</code> (<code>assertion.multipleHardBindings</code>) for a manifest with more than one hard binding assertion.</li><li><code>C2paStatusCode</code> now has <code>ASSERTION_UNDECLARED</code> (<code>assertion.undeclared</code>) for an assertion the claim does not reference.</li><li><code>C2paStatusCode</code> now has <code>CLAIM_MULTIPLE</code> (<code>claim.multiple</code>) for a manifest with more than one claim box.</li><li><code>C2paStatusCode</code> now has <code>CLAIM_CBOR_INVALID</code> (<code>claim.cbor.invalid</code>) for a claim box whose CBOR does not decode.</li><li><code>C2paStatusCode</code> now has <code>CLAIM_MALFORMED</code> (<code>claim.malformed</code>) for a claim box whose CBOR is not a map.</li></ul><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to “Changed”">​</a></h3><ul><li>A manifest-box segment whose claim does not verify the <code>c2pa.livevideo.segment</code> assertion now also reports <code>LiveVideoStatusCode.ASSERTION_INVALID</code> and <code>LiveVideoStatusCode.CONTINUITY_METHOD_INVALID</code>. This includes a claim box that does not decode.</li><li><code>ManifestBoxValidationResult.errorCodes</code> no longer repeats a <code>C2paStatusCode</code> value.</li><li><code>C2paAssertion.data</code> now holds an unsigned integer up to <code>Number.MAX_SAFE_INTEGER</code> as a number instead of a BigInt. The same applies to the assertion data that a <code>ManifestBoxContinuityValidator</code> receives. See Working with Manifest Data in the Results and Error Codes guide.</li><li>A CBOR tag other than tag 0 and tag 1 is now a plain <code>{ tag, value }</code> object in <code>C2paAssertion.data</code>. This includes tags 2, 3, 65 to 87, 258, and 55799, which were a BigInt, a typed array, a <code>Set</code>, or the tagged value. Tag 0 and tag 1 are still a <code>Date</code>.</li><li>A map key <code>__proto__</code> in a CBOR assertion is now an own property of the decoded object.</li><li>A byte string with CBOR tag 64 no longer counts as a byte string in any field, such as the <code>hash</code> of a <code>c2pa.hash.bmff.v3</code> assertion. If your signer uses the cbor-x encoder in Node.js, set <code>tagUint8Array: false</code>.</li><li>A <code>COSE_Sign1</code> structure must now carry CBOR tag 18 (<code>COSE_Sign1_Tagged</code>). A claim signature without the tag fails with <code>C2paStatusCode.CLAIM_SIGNATURE_MISMATCH</code>, and a signer binding without the tag makes its session key invalid. If your signer writes the bare array, write <code>COSE_Sign1_Tagged</code> instead.</li><li><code>validateC2paSegment</code> now throws an error for a Verifiable Segment Info without CBOR tag 18.</li><li>CBOR nested deeper than 128 levels of arrays, maps, and tags no longer decodes.</li><li>A CBOR array of integers no longer counts as a byte string in any field, such as a <code>kid</code>, a <code>signerBinding</code>, or a hash.</li><li>The VSI/EMSG Validation guide now describes the session key validity period, the accepted signer binding payloads with CBOR tag 18, and the sequence number range.</li><li>The Results and Error Codes guide now has an Invalid Session Keys section and describes the value shapes of <code>C2paAssertion.data</code>. Its error code table now describes the validity period of session keys.</li><li>The Manifest Box Validation guide now states when <code>sequenceNumber</code> is <code>null</code> and names the error code for a malformed hash.</li><li>The examples in the README and the VSI/EMSG Validation guide now check <code>isValid</code> before they use <code>sessionKeys</code>. Do not use the session keys of a result with <code>isValid: false</code>.</li><li>The code examples in the validation guides now typecheck.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to “Removed”">​</a></h3><ul><li>The package no longer has the <code>cbor-x</code> peer dependency. If you installed <code>cbor-x</code> for this package only, remove it from your dependencies.</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>validateC2paInitSegment</code> now keeps a session key that is not yet active. Segments signed with that key no longer fail with <code>LiveVideoStatusCode.SEGMENT_INVALID</code>.</li><li>The signer binding check now accepts the certificate itself or the certificate as a CBOR byte string as the signed payload.</li><li>The payload field of a signer binding must now be nil, an empty byte string, or an exact copy of the signed payload. Other content makes the session key invalid.</li><li><code>validateC2paInitSegment</code> now reports <code>LiveVideoStatusCode.SESSIONKEY_INVALID</code> for an invalid session key in the <code>c2pa.session-keys</code> assertion. An expired session key does not count as invalid. The function does not check every rule of C2PA section 18.25.2.</li><li><code>validateC2paInitSegment</code> now reads the <code>kid</code> of a session key only from its COSE key.</li><li><code>minSequenceNumber</code> and <code>validityPeriod</code> must now be unsigned integers up to <code>Number.MAX_SAFE_INTEGER</code>, and <code>createdAt</code> must be CBOR tag 0 with an RFC 3339 date-time. A session key that breaks one of these rules is invalid. If an init segment now fails, check the fields of its session keys and the signer binding.</li><li><code>validateC2paInitSegment</code> now reports <code>SESSIONKEY_INVALID</code> for a session key that it cannot verify, such as an unsupported key type. It no longer throws an error in that case.</li><li><code>validateC2paInitSegment</code> now reports <code>SESSIONKEY_INVALID</code> when the <code>c2pa.session-keys</code> assertion has no session key or holds CBOR that does not decode. This also applies in VOD Merkle mode.</li><li><code>validateC2paSegment</code> now reports <code>LiveVideoStatusCode.SEGMENT_INVALID</code> for a segment whose session key is not yet active or has expired. It no longer reports <code>SESSIONKEY_INVALID</code> for such a segment. Handle <code>SEGMENT_INVALID</code> instead, and update dashboards that count <code>livevideo.sessionkey.invalid</code> for media segments.</li><li><code>validateC2paSegment</code> now accepts a <code>sequenceNumber</code> of 2^32 or more, up to <code>Number.MAX_SAFE_INTEGER</code>. A larger value, a negative value, or a fraction causes an error that names the supported range.</li><li><code>validateC2paManifestBoxSegment</code> now accepts a <code>sequenceNumber</code> of 2^32 or more, up to <code>Number.MAX_SAFE_INTEGER</code>. A larger value, or a value that is not an unsigned integer, counts as a missing value and yields <code>sequenceNumber: null</code>.</li><li>The validation functions now fail fast on a CBOR item that declares more content than the input holds. Such a segment no longer costs seconds of processor time or gigabytes of memory.</li><li><code>validateC2paManifestBoxSegment</code> now reports <code>C2paStatusCode.ASSERTION_BMFFHASH_MALFORMED</code> when the <code>hash</code> of the <code>c2pa.hash.bmff.v3</code> assertion is not a byte string.</li><li>A <code>c2pa.hash.bmff.v3</code> exclusion must now have an <code>xpath</code> text string, and each <code>data</code> constraint must have an unsigned integer <code>offset</code> and a byte string <code>value</code>. <code>validateC2paManifestBoxSegment</code> reports <code>C2paStatusCode.ASSERTION_BMFFHASH_MALFORMED</code> for an exclusion that breaks this rule. <code>validateC2paInitSegment</code> reports <code>ASSERTION_BMFFHASH_MALFORMED</code> for a Merkle assertion and <code>LiveVideoStatusCode.INIT_INVALID</code> for a flat hash, and <code>validateC2paSegment</code> throws an error.</li><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now report <code>C2paStatusCode.CLAIM_CBOR_INVALID</code> for a claim box whose CBOR does not decode. Such a manifest no longer validates on the claim signature alone.</li><li><code>validateC2paInitSegment</code> and <code>validateC2paManifestBoxSegment</code> now report <code>C2paStatusCode.CLAIM_MALFORMED</code> for a claim box whose CBOR is not a map.</li><li>A bundle that imports only a constant from the package no longer keeps a <code>TextDecoder</code> construction or the certificate and signature constants of the package.</li></ul><h2 id="_1-3-0-2026-09-29" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.2.0...c2pa-v1.3.0" target="_blank" rel="noreferrer">1.3.0</a> - 2026-09-29 <a class="header-anchor" href="#_1-3-0-2026-09-29" aria-label="Permalink to “1.3.0 - 2026-09-29”">​</a></h2><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>C2paStatusCode.CLAIM_SIGNATURE_MISMATCH</code> now has the value <code>claimSignature.mismatch</code> from the C2PA specification (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/469" target="_blank" rel="noreferrer">#469</a>). The old value was <code>claim.signature.mismatch</code>. The constant name does not change. If your code compares <code>errorCodes</code> with the old value, compare with <code>C2paStatusCode.CLAIM_SIGNATURE_MISMATCH</code> instead. Also update logs, dashboards, and alert rules that store the old value.</li></ul><h2 id="_1-2-0-2026-09-25" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.1.3...c2pa-v1.2.0" target="_blank" rel="noreferrer">1.2.0</a> - 2026-09-25 <a class="header-anchor" href="#_1-2-0-2026-09-25" aria-label="Permalink to “1.2.0 - 2026-09-25”">​</a></h2><h3 id="security-3" tabindex="-1">Security <a class="header-anchor" href="#security-3" aria-label="Permalink to “Security”">​</a></h3><ul><li><code>validateC2paManifestBoxSegment</code> and <code>validateC2paInitSegment</code> no longer return <code>isValid: true</code> for a manifest without a verifiable claim signature. An attacker who controlled the media bytes could forge provenance without a signing key. See <a href="https://github.com/streaming-video-technology-alliance/common-media-library/security/advisories/GHSA-h5r3-7p8g-g3q2" target="_blank" rel="noreferrer">GHSA-h5r3-7p8g-g3q2</a>. A manifest without a <code>c2pa.signature</code> box now fails with <code>C2paStatusCode.CLAIM_SIGNATURE_MISSING</code>. A manifest whose claim signature has no certificate now fails with <code>C2paStatusCode.CLAIM_SIGNATURE_MISMATCH</code>. A manifest without a claim box now fails with <code>C2paStatusCode.CLAIM_MISSING</code>.</li></ul><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>C2paStatusCode.CLAIM_SIGNATURE_MISSING</code> (<code>claimSignature.missing</code>) and <code>C2paStatusCode.CLAIM_MISSING</code> (<code>claim.missing</code>).</li><li><code>ManifestBoxValidationResult.certificate</code>: the DER-encoded end-entity certificate from the claim signature (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/468" target="_blank" rel="noreferrer">#468</a>). The value is <code>null</code> when the claim signature is absent or has no certificate. You can now compare this certificate with your trust list.</li></ul><h3 id="changed-6" tabindex="-1">Changed <a class="header-anchor" href="#changed-6" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Validation guides and README: the library does not compare the certificate from the claim signature with a trust list. Check <code>isValid</code> before you use <code>merkleMaps</code>. See the new Signer Trust section of the Results and Error Codes guide.</li><li>Validation guides and README: rewritten prose for readers who do not read English as a first language. The validation guides define the term Merkle tree at its first use. Empty table cells and a code comment in the validation guides no longer use an em dash.</li><li>README: the code examples are complete. The code examples take the segment URLs as function parameters.</li></ul><h2 id="_1-1-3-2026-09-15" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.1.2...c2pa-v1.1.3" target="_blank" rel="noreferrer">1.1.3</a> - 2026-09-15 <a class="header-anchor" href="#_1-1-3-2026-09-15" aria-label="Permalink to “1.1.3 - 2026-09-15”">​</a></h2><h3 id="changed-7" tabindex="-1">Changed <a class="header-anchor" href="#changed-7" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Update <code>@svta/cml-iso-bmff</code> to 1.0.6</li><li>Update <code>@svta/cml-utils</code> to 1.6.1</li></ul><h2 id="_1-1-2-2026-08-11" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.1.1...c2pa-v1.1.2" target="_blank" rel="noreferrer">1.1.2</a> - 2026-08-11 <a class="header-anchor" href="#_1-1-2-2026-08-11" aria-label="Permalink to “1.1.2 - 2026-08-11”">​</a></h2><h3 id="changed-8" tabindex="-1">Changed <a class="header-anchor" href="#changed-8" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Update <code>@svta/cml-iso-bmff</code> to 1.0.5</li></ul><h2 id="_1-1-1-2026-07-28" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.1.0...c2pa-v1.1.1" target="_blank" rel="noreferrer">1.1.1</a> - 2026-07-28 <a class="header-anchor" href="#_1-1-1-2026-07-28" aria-label="Permalink to “1.1.1 - 2026-07-28”">​</a></h2><h3 id="changed-9" tabindex="-1">Changed <a class="header-anchor" href="#changed-9" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Update <code>@svta/cml-iso-bmff</code> to 1.0.4</li><li>Update <code>@svta/cml-utils</code> to 1.6.0</li></ul><h2 id="_1-1-0-2026-07-21" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.0.1...c2pa-v1.1.0" target="_blank" rel="noreferrer">1.1.0</a> - 2026-07-21 <a class="header-anchor" href="#_1-1-0-2026-07-21" aria-label="Permalink to “1.1.0 - 2026-07-21”">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to “Added”">​</a></h3><ul><li>Custom continuity method support in manifest-box validation (C2PA §19.3.2 / §19.7.2): <code>validateC2paManifestBoxSegment</code> accepts an optional <code>continuityValidator</code> to verify implementer-defined continuity methods; segments declaring an unregistered method keep failing with <code>livevideo.continuityMethod.invalid</code> per spec</li><li><code>LiveVideoStatusCode.CONTINUITY_METHOD_UNSUPPORTED</code> (<code>livevideo.continuityMethod.unsupported</code>), emitted alongside <code>continuityMethod.invalid</code> so consumers can distinguish an unverifiable custom method from a broken chain</li><li><code>ManifestBoxValidationOptions</code> and <code>ManifestBoxContinuityValidator</code> types</li><li>VOD Merkle validation (C2PA §15.12.2 / §18.6): <code>validateC2paMerkleSegment</code> verifies fragmented MP4 media segments against the merkle maps from the init manifest — per-track Merkle proof verification with <code>location</code> continuity enforced via caller-held state</li><li><code>MerkleMap</code>, <code>MerkleSegmentState</code>, and <code>MerkleSegmentValidation</code> types</li><li><code>validateC2paInitSegment</code> extracts merkle maps from the <code>c2pa.hash.bmff.v3</code> assertion, validates each entry&#39;s <code>initHash</code> binding, and returns them as <code>merkleMaps</code></li><li><code>C2paStatusCode</code> entries <code>assertion.bmffHash.malformed</code> and <code>assertion.bmffHash.mismatch</code></li></ul><h3 id="changed-10" tabindex="-1">Changed <a class="header-anchor" href="#changed-10" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>InitSegmentValidation</code> gains a <code>merkleMaps</code> field; <code>SESSIONKEY_INVALID</code> is no longer raised for VOD Merkle streams</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>validateC2paManifestBoxSegment</code> now enforces the 8-byte box-offset prefix (C2PA §18.6.2) when verifying the flat <code>c2pa.hash.bmff.v3</code> assertion hash, matching c2pa-rs; unprefixed flat hashes are no longer accepted. The VSI path (§19.7.3) keeps dual-mode validation since its hash comes from the VSI map, not a §18.6.2 assertion.</li><li><code>validateC2paInitSegment</code> now enforces the 8-byte box-offset prefix (C2PA §18.6.2) when verifying the flat <code>c2pa.hash.bmff.v3</code> assertion hash, matching c2pa-rs; unprefixed flat hashes are no longer accepted</li><li>The module-scope hex lookup table in <code>bytesToHex</code> is now marked side-effect free so consumer bundlers can drop it when unused (follow-up to the module-scope side-effect audit in <a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/382" target="_blank" rel="noreferrer">#382</a>)</li><li>Top-level <code>TextDecoder</code> and <code>TextEncoder</code> instantiations are now marked side-effect free so consumer bundlers can drop them when unused (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/382" target="_blank" rel="noreferrer">#382</a>)</li></ul><h2 id="_1-0-1-2026-05-13" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/c2pa-v1.0.0...c2pa-v1.0.1" target="_blank" rel="noreferrer">1.0.1</a> - 2026-05-13 <a class="header-anchor" href="#_1-0-1-2026-05-13" aria-label="Permalink to “1.0.1 - 2026-05-13”">​</a></h2><h3 id="changed-11" tabindex="-1">Changed <a class="header-anchor" href="#changed-11" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Update <code>@svta/cml-iso-bmff</code> to 1.0.2</li><li>Update <code>@svta/cml-utils</code> to 1.5.0</li></ul><h2 id="_1-0-0-2026-04-14" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/tree/c2pa-v1.0.0" target="_blank" rel="noreferrer">1.0.0</a> - 2026-04-14 <a class="header-anchor" href="#_1-0-0-2026-04-14" aria-label="Permalink to “1.0.0 - 2026-04-14”">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to “Added”">​</a></h3><ul><li>Package scaffold with core C2PA types (<code>C2paManifest</code>, <code>C2paAssertion</code>, <code>C2paSignatureInfo</code>)</li><li><code>LiveVideoStatusCode</code> — standardized C2PA §19.7 error code constants</li><li>JUMBF box parsing (ISO 19566-5)</li><li>COSE_Sign1 cryptographic support (RFC 9052): decoding, signature verification, key conversion, signer binding</li><li>X.509 certificate parsing (issuer, validity period)</li><li>BMFF content hash computation and validation</li><li>EMSG box parsing (ISO 14496-12, v0 and v1)</li><li>VSI (Verifiable Segment Info) CBOR map decoding</li><li>Sequence number validation (monotonic, gap/duplicate detection)</li><li><code>validateC2paInitSegment(bytes)</code> — validate init segment: manifest, certificate, BMFF hash, session keys</li><li><code>validateC2paSegment(bytes, sessionKeys, state?)</code> — validate media segment via VSI/EMSG method (§19.7.3)</li><li><code>validateC2paManifestBoxSegment(bytes, lastId, state?)</code> — validate manifest-box segment (§19.7.2)</li><li>All validation results return <code>isValid</code> + <code>errorCodes</code> with C2PA failure codes</li></ul>`,73)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};